  // your code here
  // return { fields, append, remove, update, move }
}

test_suite:
test('starts with initial fields', () => {
  const { result } = renderHook(() => useFormArray([{ name: 'a' }, { name: 'b' }]));
  expect(result.current.fields).toEqual([{ name: 'a' }, { name: 'b' }]);
});

test('append adds item to end', () => {
  const { result } = renderHook(() => useFormArray<{ name: string }>([]));
  act(() => result.current.append({ name: 'Alice' }));
  expect(result.current.fields).toEqual([{ name: 'Alice' }]);
});

test('remove deletes item at index', () => {
  const { result } = renderHook(() => useFormArray(['a', 'b', 'c']));
  act(() => result.current.remove(1));
  expect(result.current.fields).toEqual(['a', 'c']);
});

test('update changes value at index', () => {
  const { result } = renderHook(() => useFormArray(['a', 'b', 'c']));
  act(() => result.current.update(1, 'z'));
  expect(result.current.fields).toEqual(['a', 'z', 'c']);
});

test('move reorders items', () => {
  const { result } = renderHook(() => useFormArray(['a', 'b', 'c', 'd']));
  act(() => result.current.move(0, 2));
  expect(result.current.fields).toEqual(['b', 'c', 'a', 'd']);
});

// __hidden__
test('append multiple times', () => {
  const { result } = renderHook(() => useFormArray<number>([]));
  act(() => { result.current.append(1); result.current.append(2); result.current.append(3); });
  expect(result.current.fields).toEqual([1, 2, 3]);
});

solution:
import { useState, useCallback } from 'react';

export function useFormArray<T>(initial: T[]) {
  const [fields, setFields] = useState<T[]>(initial);

  const append = useCallback((item: T) => {
    setFields(prev => [...prev, item]);
  }, []);

  const remove = useCallback((index: number) => {
    setFields(prev => prev.filter((_, i) => i !== index));
  }, []);

  const update = useCallback((index: number, value: T) => {
    setFields(prev => prev.map((item, i) => i === index ? value : item));
  }, []);

  const move = useCallback((from: number, to: number) => {
    setFields(prev => {
      const next = [...prev];
      const [item] = next.splice(from, 1);
      next.splice(to, 0, item);
      return next;
    });
  }, []);

  return { fields, append, remove, update, move };
}
